3	import (
4		"context"
5		"errors"
6		"fmt"
7		"io"
8		"log/slog"
9		"os"
10		"os/exec"
11		"strings"
12		"sync"
13		"time"
14	
15		"github.com/entireio/cli/cmd/entire/cli/checkpoint/remote"
16		"github.com/entireio/cli/cmd/entire/cli/logging"
17		"github.com/entireio/cli/cmd/entire/cli/settings"
18		"github.com/entireio/cli/perf"
19	
20		"github.com/go-git/go-git/v6"
21		"github.com/go-git/go-git/v6/plumbing"
22		"github.com/go-git/go-git/v6/plumbing/object"
23	)
24	
25	// pushBranchIfNeeded pushes a branch to the given target if it has unpushed changes.
26	// The target can be a remote name (e.g., "origin") or a URL for direct push.
27	// When pushing to a URL, the "has unpushed" optimization is skipped since there are
28	// no remote tracking refs — git itself handles the no-op case.
29	// Does not check any settings — callers are responsible for gating.
30	func pushBranchIfNeeded(ctx context.Context, target, branchName string) error {
31		repo, err := OpenRepository(ctx)
32		if err != nil {
33			return nil
34		}
35		defer repo.Close()
36	
37		// Check if branch exists locally
38		branchRef := plumbing.NewBranchReferenceName(branchName)
39		localRef, err := repo.Reference(branchRef, true)
40		if err != nil {
41			// No branch, nothing to push
42			return nil
43		}
44	
45		// Only check remote tracking refs when target is a remote name (not a URL).
46		// URLs don't have tracking refs, so we always attempt the push and let git handle it.
47		if !remote.IsURL(target) && !hasUnpushedSessionsCommon(repo, target, localRef.Hash(), branchName) {
48			return nil
49		}
50	
51		return doPushBranch(ctx, target, branchName)
52	}
53	
54	// hasUnpushedSessionsCommon checks if the local branch differs from the remote.
55	// Returns true if there's any difference that needs syncing (local ahead, remote ahead, or diverged).
56	func hasUnpushedSessionsCommon(repo *git.Repository, remoteName string, localHash plumbing.Hash, branchName string) bool {
57		// Check for remote tracking ref: refs/remotes/<remoteName>/<branch>
58		remoteRefName := plumbing.NewRemoteReferenceName(remoteName, branchName)
59		remoteRef, err := repo.Reference(remoteRefName, true)
60		if err != nil {
61			// Remote branch doesn't exist yet - we have content to push
62			return true
63		}
64	
65		// If local and remote point to same commit, nothing to sync
66		// This is the only case where we skip - any difference needs handling
67		return localHash != remoteRef.Hash()
68	}
69	
70	func displayPushTarget(target string) string {
71		if remote.IsURL(target) {
72			return "checkpoint remote"
73		}
74		return target
75	}
76	
77	// doPushBranch pushes the given branch to the target with fetch+merge recovery.
78	// The target can be a remote name or a URL.
79	func doPushBranch(ctx context.Context, target, branchName string) error { //nolint:unparam // callers treat push failures as non-fatal but keep an error-shaped boundary.
80		displayTarget := displayPushTarget(target)
81	
82		fmt.Fprintf(os.Stderr, "[entire] Pushing %s to %s...", branchName, displayTarget)
83		stop := startProgressDots(os.Stderr)
84	
85		// Try pushing first
86		result, err := tryPushSessionsCommon(ctx, target, branchName)
87		if err == nil {
88			finishPush(ctx, stop, result, target)
89			return nil
90		}
91		stop("")
92	
93		// Protected refs cannot be fixed by syncing and retrying.
94		var protectedErr *protectedRefError
95		if errors.As(err, &protectedErr) {
96			printProtectedRefBlock(os.Stderr, branchName, target)
97			return nil
98		}
99	
100		// Push failed - likely non-fast-forward. Try to fetch and rebase.
101		// Spanned (with the network fetch as a child) so the trace distinguishes
102		// "the raw push is slow" from "we keep hitting contention and re-syncing".
103		fmt.Fprintf(os.Stderr, "[entire] Syncing %s with remote...", branchName)
104		stop = startProgressDots(os.Stderr)
105	
106		frCtx, fetchRebaseSpan := perf.Start(ctx, "fetch_and_rebase")
107		syncErr := fetchAndRebaseSessionsCommon(frCtx, target, branchName)
108		fetchRebaseSpan.RecordError(syncErr)
109		fetchRebaseSpan.End()
110		if syncErr != nil {
111			stop("")
112			fmt.Fprintf(os.Stderr, "[entire] Warning: couldn't sync %s: %v\n", branchName, syncErr)
113			printCheckpointRemoteHint(target)
114			return nil // Don't fail the main push
115		}
116		stop(" done")
117	
118		// Try pushing again after rebase
119		fmt.Fprintf(os.Stderr, "[entire] Pushing %s to %s...", branchName, displayTarget)
120		stop = startProgressDots(os.Stderr)
121	
122		if result, err := tryPushSessionsCommon(ctx, target, branchName); err != nil {
123			stop("")
124			fmt.Fprintf(os.Stderr, "[entire] Warning: failed to push %s after sync: %v\n", branchName, err)
125			printCheckpointRemoteHint(target)
126		} else {
127			finishPush(ctx, stop, result, target)
128		}
129	
130		return nil
131	}
132	
133	// printCheckpointRemoteHint prints a hint when a push to a checkpoint URL fails.
134	// Only prints when the target is a URL (not the user's default remote).
135	func printCheckpointRemoteHint(target string) {
136		if !remote.IsURL(target) {
137			return
138		}
139		fmt.Fprintln(os.Stderr, "[entire] A checkpoint remote is configured in Entire settings (.entire/settings.json or .entire/settings.local.json) but could not be reached.")
140		fmt.Fprintln(os.Stderr, "[entire] Checkpoints are saved locally but not synced. Ensure you have access to the checkpoint remote.")
141	}
142	
143	// settingsHintOnce ensures the settings commit hint prints at most once per process.
144	var settingsHintOnce sync.Once
145	
146	// printSettingsCommitHint prints a hint after a successful checkpoint remote push
147	// when the committed .entire/settings.json does not contain a checkpoint_remote config.
148	// entire.io discovers the external checkpoint repo by reading the committed project
149	// settings, so the checkpoint_remote must be present in HEAD:.entire/settings.json
150	// (not just in settings.local.json or uncommitted local changes).
151	// Uses sync.Once to avoid duplicates when multiple branches/refs are pushed in a
152	// single pre-push invocation.
153	func printSettingsCommitHint(ctx context.Context, target string) {
154		if !remote.IsURL(target) {
155			return
156		}
157		settingsHintOnce.Do(func() {
158			if isCheckpointRemoteCommitted(ctx) {
159				return
160			}
161			fmt.Fprintln(os.Stderr, "[entire] Note: Checkpoints were pushed to a separate checkpoint remote, but .entire/settings.json does not contain checkpoint_remote in the latest commit. entire.io will not be able to discover these checkpoints until checkpoint_remote is committed and pushed in .entire/settings.json.")
162		})
163	}
164	
165	// isCheckpointRemoteCommitted returns true if the committed .entire/settings.json
166	// at HEAD contains a valid checkpoint_remote configuration. This is the true
167	// discoverability check: entire.io reads from committed project settings, not from
168	// local overrides or uncommitted changes.
169	func isCheckpointRemoteCommitted(ctx context.Context) bool {
170		cmd := exec.CommandContext(ctx, "git", "show", "HEAD:.entire/settings.json")
171		output, err := cmd.Output()
172		if err != nil {
173			return false // file doesn't exist at HEAD
174		}
175		// Parse the committed content and check for checkpoint_remote
176		committed, err := settings.LoadFromBytes(output)
177		if err != nil {
178			return false
179		}
180		return committed.GetCheckpointRemote() != nil
181	}
182	
183	// pushResult describes what happened during a push attempt.
184	type pushResult struct {
185		// upToDate is true when the remote already had all commits (nothing transferred).
186		upToDate bool
187	}
188	
189	// parsePushResult checks git push --porcelain output for ref status flags.
190	// In porcelain mode, each ref gets a tab-delimited status line:
191	//
192	//	<flag>\t<from>:<to>\t<summary>
193	//
194	// where flag '=' means the ref was already up-to-date. This is locale-independent,
195	// unlike the human-readable "Everything up-to-date" message.
196	func parsePushResult(output string) pushResult {
197		for _, line := range strings.Split(output, "\n") {
198			if strings.HasPrefix(line, "=\t") {
199				return pushResult{upToDate: true}
200			}
201		}
202		return pushResult{upToDate: false}
203	}
204	
205	// finishPush stops the progress dots and prints "already up-to-date" or "done"
206	// depending on the push result. Only prints the settings commit hint when new
207	// content was actually pushed.
208	func finishPush(ctx context.Context, stop func(string), result pushResult, target string) {
209		if result.upToDate {
210			stop(" already up-to-date")
211		} else {
212			stop(" done")
213			printSettingsCommitHint(ctx, target)
214		}
215	}
216	
217	// tryPushSessionsCommon attempts to push the sessions branch.
218	func tryPushSessionsCommon(ctx context.Context, remoteName, branchName string) (pushResult, error) {
219		ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
220		defer cancel()
221	
222		// Span the actual `git push` subprocess: on a slow remote (e.g. a custom
223		// git transport) this is typically where pre-push time is spent. Called once
224		// per push attempt, so a retry after fetch+rebase shows up as a second
225		// git_push step (git_push~1) in the trace. A rejected first push records an
226		// error flag, which signals the recovery path was taken.
227		_, pushSpan := perf.Start(ctx, "git_push")
228		result, err := remote.Push(ctx, remoteName, branchName)
229		pushSpan.RecordError(err)
230		pushSpan.End()
231	
232		outputStr := result.Output
233		if err != nil {
234			return pushResult{}, classifyPushFailure(ctx, outputStr, err)
235		}
236	
237		return parsePushResult(outputStr), nil
238	}
239	
240	// protectedRefError means the remote is blocking writes to the ref itself.
241	type protectedRefError struct {
242		output string
243	}
244	
245	func (e *protectedRefError) Error() string {
246		return "remote rejected push to protected ref"
247	}
248	
249	// isProtectedRefRejection detects GitHub ruleset and branch-protection failures.
250	func isProtectedRefRejection(output string) bool {
251		return strings.Contains(output, "GH013") ||
252			strings.Contains(output, "Cannot update this protected ref") ||
253			strings.Contains(output, "protected branch hook declined")
254	}
255	
256	var errNonFastForward = errors.New("non-fast-forward")
257	
258	func isNonFastForwardRejection(output string) bool {
259		if strings.Contains(output, "non-fast-forward") {
260			return true
261		}
262		for _, line := range strings.Split(output, "\n") {
263			if strings.Contains(line, "[rejected]") && strings.Contains(line, "(fetch first)") {
264				return true
265			}
266		}
267		return strings.Contains(output, "Updates were rejected because the tip of your current branch is behind") ||
268			strings.Contains(output, "Updates were rejected because the remote contains work that you do not have locally")
269	}
270	
271	// classifyPushOutput maps failing push stderr to a typed error.
272	func classifyPushOutput(output string) error {
273		if isProtectedRefRejection(output) {
274			return &protectedRefError{output: output}
275		}
276		if isNonFastForwardRejection(output) {
277			return errNonFastForward
278		}
279		if strings.TrimSpace(output) == "" {
280			return errors.New("push failed")
281		}
282		return fmt.Errorf("push failed: %s", output)
283	}
284	
285	func classifyPushFailure(ctx context.Context, output string, pushErr error) error {
286		if strings.TrimSpace(output) != "" {
287			if pushErr != nil {
288				logging.Debug(ctx, "git push failed",
289					slog.String("error", pushErr.Error()),
290					slog.String("output", output),
291				)
292			}
293			return classifyPushOutput(output)
294		}
295		if pushErr != nil {
296			logging.Debug(ctx, "git push failed without output",
297				slog.String("error", pushErr.Error()),
298			)
299			return fmt.Errorf("push failed: %w", pushErr)
300		}
301		return errors.New("push failed")
302	}
303	
304	// printProtectedRefBlock explains that checkpoint syncing was blocked remotely.
305	func printProtectedRefBlock(w io.Writer, ref, target string) {
306		const banner = "[entire] ============================================================"
307		displayTarget := displayPushTarget(target)
308		fmt.Fprintln(w, banner)
309		fmt.Fprintf(w, "[entire] BLOCKED: remote rejected push to %s\n", ref)
310		fmt.Fprintln(w, "[entire] Reason:  GitHub branch protection or repository ruleset (e.g. GH013)")
311		fmt.Fprintf(w, "[entire] Target:  %s\n", displayTarget)
312		fmt.Fprintln(w, "[entire] Impact:  checkpoints are saved locally but NOT synced to this remote.")
313		fmt.Fprintln(w, "[entire] Action:  allow pushes to `entire/*` in your ruleset, or set")
314		fmt.Fprintln(w, "[entire]          `checkpoint_remote` in .entire/settings.json to a separate repo.")
315		fmt.Fprintln(w, banner)
316	}
317	
318	// fetchAndRebaseSessionsCommon fetches remote sessions and rebases local commits
319	// on top of the remote tip. Since checkpoint shards use unique paths, rebases
320	// always apply cleanly.
321	// The target can be a remote name or a URL.
322	func fetchAndRebaseSessionsCommon(ctx context.Context, target, branchName string) error {
323		ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
324		defer cancel()
325	
326		fetchTarget, err := remote.ResolveFetchTarget(ctx, target)
327		if err != nil {
328			return fmt.Errorf("resolve fetch target: %w", err)
329		}
330	
331		// Determine fetch refspec. When the resolved fetch target is a URL, use a
332		// temp ref; when it's still a remote name, use the standard remote-tracking
333		// ref.
334		var fetchedRefName plumbing.ReferenceName
335		var refSpec string
336		usedTempRef := remote.IsURL(fetchTarget)
337		if usedTempRef {
338			tmpRef := "refs/entire-fetch-tmp/" + branchName
339			refSpec = fmt.Sprintf("+refs/heads/%s:%s", branchName, tmpRef)
340			fetchedRefName = plumbing.ReferenceName(tmpRef)
341		} else {
342			refSpec = fmt.Sprintf("+refs/heads/%s:refs/remotes/%s/%s", branchName, target, branchName)
343			fetchedRefName = plumbing.NewRemoteReferenceName(target, branchName)
344		}
345	
346		// Use git CLI for fetch (go-git's fetch can be tricky with auth).
347		// Do NOT --unshallow here: on a shallow repo with deep history (e.g. a
348		// shared monorepo), --unshallow downloads the whole repository because
349		// git treats shallow as a global property of the clone, not per-ref.
350		// The downstream reconcile/rebase paths walk only commits visible past
351		// .git/shallow (collectCommitChain / collectCommitsSince), so the
352		// missing pre-shallow history isn't needed to produce a correct rebase.
353		// Span the fetch separately so a slow sync can be attributed to the network
354		// fetch versus the local reconcile/rebase that follows it.
355		_, fetchSpan := perf.Start(ctx, "git_fetch")
356		fetchOutput, fetchErr := remote.Fetch(ctx, remote.FetchOptions{
357			Remote:   fetchTarget,
358			RefSpecs: []string{refSpec},
359			NoTags:   true,
360		})
361		fetchSpan.RecordError(fetchErr)
362		fetchSpan.End()
363		if fetchErr != nil {
364			return fmt.Errorf("fetch failed: %s", fetchOutput)
365		}
366	
367		repo, err := OpenRepository(ctx)
368		if err != nil {
369			return fmt.Errorf("failed to open git repository: %w", err)
370		}
371		defer repo.Close()
372	
373		// Reconcile disconnected metadata branches before rebasing.
374		// The fetch above updated the remote-tracking ref, so reconciliation
375		// can compare fresh local vs remote. If disconnected (empty-orphan bug),
376		// this cherry-picks local commits onto remote tip, updating the local ref.
377		// If reconciliation fails, abort — proceeding to rebase on disconnected
378		// branches would silently combine unrelated histories.
379		if reconcileErr := ReconcileDisconnectedMetadataBranch(ctx, repo, fetchedRefName, os.Stderr); reconcileErr != nil {
380			return fmt.Errorf("metadata reconciliation failed: %w", reconcileErr)
381		}
382	
383		// Get local branch (re-read after potential reconciliation update)
384		localRef, err := repo.Reference(plumbing.NewBranchReferenceName(branchName), true)
385		if err != nil {
386			return fmt.Errorf("failed to get local ref: %w", err)
387		}
388	
389		// Get fetched ref (remote-tracking or temp ref, updated by the fetch above)
390		remoteRef, err := repo.Reference(fetchedRefName, true)
391		if err != nil {
392			return fmt.Errorf("failed to get remote ref: %w", err)
393		}
394	
395		// If local is already at or behind remote, fast-forward
396		if localRef.Hash() == remoteRef.Hash() {
397			return nil
398		}
399	
400		// Find merge base
401		repoPath, err := getRepoPath(repo)
402		if err != nil {
403			return fmt.Errorf("failed to get repo path: %w", err)
404		}
405		mergeBase, err := getMergeBase(ctx, repoPath, localRef.Hash().String(), remoteRef.Hash().String())
406		if err != nil {
407			return fmt.Errorf("failed to find merge base: %w", err)
408		}
409	
410		// If local is ancestor of remote (merge base == local), fast-forward to remote
411		if mergeBase == localRef.Hash() {
412			ref := plumbing.NewHashReference(plumbing.NewBranchReferenceName(branchName), remoteRef.Hash())
413			if err := repo.Storer.SetReference(ref); err != nil {
414				return fmt.Errorf("failed to fast-forward branch ref: %w", err)
415			}
416			if usedTempRef {
417				_ = repo.Storer.RemoveReference(fetchedRefName) //nolint:errcheck // cleanup is best-effort
418			}
419			return nil
420		}
421	
422		// Collect commits reachable from local but not from remote and cherry-pick
423		// them onto the remote tip. This preserves local-only commits even when the
424		// local metadata branch already contains old merge commits, while avoiding
425		// replaying shared ancestors older than the true merge-base.
426		localCommits, err := collectCommitsSince(ctx, repo, repoPath, localRef.Hash(), remoteRef.Hash())
427		if err != nil {
428			return fmt.Errorf("failed to collect local commits: %w", err)
429		}
430	
431		if len(localCommits) == 0 {
432			// No local-only commits — just point to remote
433			ref := plumbing.NewHashReference(plumbing.NewBranchReferenceName(branchName), remoteRef.Hash())
434			if err := repo.Storer.SetReference(ref); err != nil {
435				return fmt.Errorf("failed to update branch ref: %w", err)
436			}
437			if usedTempRef {
438				_ = repo.Storer.RemoveReference(fetchedRefName) //nolint:errcheck // cleanup is best-effort
439			}
440			return nil
441		}
442	
443		shallow, err := loadShallowHashes(ctx, repoPath)
444		if err != nil {
445			return fmt.Errorf("failed to load shallow boundaries: %w", err)
446		}
447	
448		newTip, err := cherryPickOnto(ctx, repo, remoteRef.Hash(), localCommits, shallow)
449		if err != nil {
450			return fmt.Errorf("failed to rebase local commits onto remote: %w", err)
451		}
452	
453		// Update branch ref
454		newRef := plumbing.NewHashReference(plumbing.NewBranchReferenceName(branchName), newTip)
455		if err := repo.Storer.SetReference(newRef); err != nil {
456			return fmt.Errorf("failed to update branch ref: %w", err)
457		}
458	
459		// Clean up temp ref if we used one (best-effort, not critical if it fails)
460		if usedTempRef {
461			_ = repo.Storer.RemoveReference(fetchedRefName) //nolint:errcheck // cleanup is best-effort
462		}
463	
464		return nil
465	}
466	
467	// getMergeBase returns the merge base hash of two commits, or an error if they
468	// have no common ancestor.
469	func getMergeBase(ctx context.Context, repoPath, hashA, hashB string) (plumbing.Hash, error) {
470		ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
471		defer cancel()
472	
473		cmd := exec.CommandContext(ctx, "git", "merge-base", hashA, hashB)
474		cmd.Dir = repoPath
475		output, err := cmd.Output()
476		if err != nil {
477			var exitErr *exec.ExitError
478			if errors.As(err, &exitErr) && exitErr.ExitCode() == 1 {
479				return plumbing.ZeroHash, errNoMergeBase
480			}
481			return plumbing.ZeroHash, fmt.Errorf("git merge-base failed: %w", err)
482		}
483	
484		mergeBase := strings.TrimSpace(string(output))
485		if mergeBase == "" {
486			return plumbing.ZeroHash, errNoMergeBase
487		}
488		return plumbing.NewHash(mergeBase), nil
489	}
490	
491	// collectCommitsSince returns non-merge commits reachable from tip but not from
492	// exclude, ordered oldest-first in topological order.
493	func collectCommitsSince(ctx context.Context, repo *git.Repository, repoPath string, tip, exclude plumbing.Hash) ([]*object.Commit, error) {
494		ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
495		defer cancel()
496	
497		// cherryPickOnto computes each commit's delta against its first parent, so
498		// replaying merge commits would incorrectly re-apply changes that arrived via
499		// non-first-parent history. Limit the replay set to non-merge commits.
500		cmd := exec.CommandContext(ctx, "git", "rev-list", "--reverse", "--topo-order", "--no-merges", exclude.String()+".."+tip.String())
501		cmd.Dir = repoPath
502		output, err := cmd.Output()
503		if err != nil {
504			return nil, fmt.Errorf("git rev-list failed: %w", err)
505		}
506	
507		lines := strings.Fields(string(output))
508		if len(lines) > MaxCommitTraversalDepth {
509			return nil, fmt.Errorf("commit chain exceeded %d commits; aborting rebase", MaxCommitTraversalDepth)
510		}
511	
512		commits := make([]*object.Commit, 0, len(lines))
513		for _, line := range lines {
514			hash := plumbing.NewHash(line)
515			commit, commitErr := repo.CommitObject(hash)
516			if commitErr != nil {
517				return nil, fmt.Errorf("failed to get commit %s: %w", hash, commitErr)
518			}
519			if len(commit.ParentHashes) > 1 {
520				continue
521			}
522			commits = append(commits, commit)
523		}
524	
525		return commits, nil
526	}
527	
528	// startProgressDots prints dots to w every second until the returned stop function
529	// is called. The stop function prints the given suffix and a newline.
530	func startProgressDots(w io.Writer) func(suffix string) {
531		done := make(chan struct{})
532		stopped := make(chan struct{})
533		go func() {
534			defer close(stopped)
535			ticker := time.NewTicker(time.Second)
536			defer ticker.Stop()
537			for {
538				select {
539				case <-done:
540					return
541				case <-ticker.C:
542					fmt.Fprint(w, ".")
543				}
544			}
545		}()
546		return func(suffix string) {
547			close(done)
548			<-stopped // Wait for goroutine to finish before writing suffix
549			fmt.Fprintln(w, suffix)
550		}
551	}
552

