281	func DeriveCheckpointURL(pushRemoteURL string, config *settings.CheckpointRemoteConfig) (string, error) {
282		info, err := gitremote.ParseURL(pushRemoteURL)
283		if err != nil {
284			return "", fmt.Errorf("cannot parse push remote URL: %w", err)
285		}
286		return deriveCheckpointURLFromInfo(info, config)
287	}
