289	// ExtractOwnerFromRemoteURL extracts the owner component from a git remote URL.
290	func ExtractOwnerFromRemoteURL(rawURL string) string {
291		return gitremote.ExtractOwnerFromRemoteURL(rawURL)
292	}
293	
294	// isDerivableProtocol reports whether deriveCheckpointURLFromInfo can map the
295	// protocol to a checkpoint URL (i.e. it's a real git transport, not a remote
296	// helper scheme like entire:// or a local file://).
297	func isDerivableProtocol(protocol string) bool {
298		return protocol == ProtocolSSH || protocol == ProtocolHTTPS
299	}
300	
301	func deriveCheckpointURLFromInfo(info *Info, config *settings.CheckpointRemoteConfig) (string, error) {
302		switch info.Protocol {
303		case ProtocolSSH:
304			// SCP-style (git@host:repo) doesn't support ports. When a non-default
305			// port is set (e.g., from ssh://git@host:2222/...), use the ssh:// URL form.
306			if info.Port != "" {
307				return fmt.Sprintf("ssh://git@%s/%s.git", info.HostPort(), config.Repo), nil
308			}
309			return fmt.Sprintf("git@%s:%s.git", info.Host, config.Repo), nil
310		case ProtocolHTTPS:
311			return fmt.Sprintf("https://%s/%s.git", info.HostPort(), config.Repo), nil
312		default:
313			return "", fmt.Errorf("unsupported protocol %q in origin remote", info.Protocol)
314		}
315	}
316	
317	// originalURLConfigKey is the git config option, under remote.<name>., where
318	// entiredb's `entire-repo mirror use` records the URL a remote had before it was
319	// switched to entire://. It is the most faithful record of the endpoint and auth
320	// method the user had for that remote.
321	const originalURLConfigKey = "entiredb-original-url"
322	
323	// resolveProviderCheckpointURL builds the checkpoint URL for the configured
324	// provider, choosing the transport from what's already configured for that
325	// endpoint. It is the fallback used when the push/origin remote's protocol can't
326	// be mapped to a git transport (e.g. entire://, file://): the configured
327	// checkpoint_remote names a concrete provider, so checkpoints go there rather
328	// than being misrouted to the origin remote.
329	//
330	// Transport precedence:
331	//  1. The remote's pre-mirror URL (remote.<name>.entiredb-original-url) — the
332	//     endpoint and scheme the remote used before `entire-repo mirror use`
333	//     switched it to entire://. Reused verbatim (host + scheme + port).
334	//  2. ENTIRE_CHECKPOINT_TOKEN set -> HTTPS on the provider host (the token is
335	//     the credential).
336	//  3. An existing remote already targets the provider host -> reuse its scheme,
337	//     so checkpoints use the same auth the user already has for that endpoint.
338	//  4. Otherwise SSH on the provider host.
339	//
340	// Returns ok=false when no transport can be determined (unknown provider with no
341	// usable signal), in which case the caller falls back to the origin remote.
342	func resolveProviderCheckpointURL(config *settings.CheckpointRemoteConfig, remoteName, dir string) (string, bool) {
343		repo, err := openRepoAt(dir)
344		if err != nil {
345			repo = nil // Fall back to env/provider-only signals.
346		}
347	
348		info, ok := pickProviderTransport(repo, config, remoteName)
349		if !ok {
350			return "", false
351		}
352		url, err := deriveCheckpointURLFromInfo(info, config)
353		if err != nil {
354			return "", false
355		}
356		return url, true
357	}
358	
359	// pickProviderTransport returns the protocol/host/port to use when deriving a
360	// checkpoint URL, following the precedence documented on
361	// resolveProviderCheckpointURL.
362	func pickProviderTransport(repo *git.Repository, config *settings.CheckpointRemoteConfig, remoteName string) (*Info, bool) {
363		// 1. The remote's saved pre-mirror URL: the endpoint and auth the user had.
364		if repo != nil {
365			if original := originalRemoteURL(repo, remoteName); original != "" {
366				if info, err := gitremote.ParseURL(original); err == nil && isDerivableProtocol(info.Protocol) {
367					return info, true
368				}
369			}
370		}
371	
372		host, hostOK := providerHost(config.Provider)
373	
374		// 2. Explicit token -> HTTPS on the provider host.
375		if hostOK && strings.TrimSpace(os.Getenv(CheckpointTokenEnvVar)) != "" {
376			return &Info{Protocol: ProtocolHTTPS, Host: host}, true
377		}
378	
379		// 3. An existing remote already targeting the provider host -> reuse scheme.
380		if hostOK && repo != nil {
381			if info, ok := findRemoteInfoForHost(repo, host); ok {
382				return &Info{Protocol: info.Protocol, Host: info.Host, Port: info.Port}, true
383			}
384		}
385	
386		// 4. Default to SSH on the provider host.
387		if hostOK {
388			return &Info{Protocol: ProtocolSSH, Host: host}, true
389		}
390	
391		return nil, false
392	}
393	
394	// openRepoAt opens the git repository at dir (current directory when dir is
395	// empty), walking up to the enclosing .git directory.
396	func openRepoAt(dir string) (*git.Repository, error) {
397		if dir == "" {
398			dir = "."
399		}
400		repo, err := git.PlainOpenWithOptions(dir, &git.PlainOpenOptions{DetectDotGit: true})
401		if err != nil {
402			return nil, fmt.Errorf("open git repository: %w", err)
403		}
404		return repo, nil
405	}
406	
407	// originalRemoteURL returns the pre-mirror URL saved by `entire-repo mirror use`
408	// in remote.<name>.entiredb-original-url, or "" when absent.
409	func originalRemoteURL(repo *git.Repository, remoteName string) string {
410		cfg, err := repo.Config()
411		if err != nil {
412			return ""
413		}
414		return cfg.Raw.Section("remote").Subsection(remoteName).Option(originalURLConfigKey)
415	}
416	
417	// findRemoteInfoForHost returns the parsed Info of the first configured git
418	// remote (in deterministic name order) whose host matches host and whose
419	// protocol is a usable git transport (ssh/https). entire:// and other
420	// non-transport remotes are ignored.
421	func findRemoteInfoForHost(repo *git.Repository, host string) (*Info, bool) {
422		cfg, err := repo.Config()
423		if err != nil {
424			return nil, false
425		}
426		names := make([]string, 0, len(cfg.Remotes))
427		for name := range cfg.Remotes {
428			names = append(names, name)
429		}
430		sort.Strings(names)
431		for _, name := range names {
432			for _, rawURL := range cfg.Remotes[name].URLs {
433				info, err := gitremote.ParseURL(rawURL)
434				if err != nil {
435					continue
436				}
437				if strings.EqualFold(info.Host, host) && isDerivableProtocol(info.Protocol) {
438					return info, true
439				}
440			}
441		}
442		return nil, false
443	}
444	
445	func deriveTokenOriginURL(originURL string) (string, bool) {
446		info, err := gitremote.ParseURL(originURL)
447		if err != nil {
448			return "", false
449		}
450		if info.Host == "" || info.Owner == "" || info.Repo == "" {
451			return "", false
452		}
453		// Keep the port only when the source was already HTTPS. SSH ports
454		// (e.g., :2222) don't map to HTTPS ports on the same host.
455		hostPort := info.Host
456		if info.Protocol == ProtocolHTTPS {
457			hostPort = info.HostPort()
458		}
459		return fmt.Sprintf("https://%s/%s/%s.git", hostPort, info.Owner, info.Repo), true
460	}
461	
462	func providerHost(provider string) (string, bool) {
463		switch strings.ToLower(strings.TrimSpace(provider)) {
464		case "github":
465			return "github.com", true
466		case "gitlab":
467			return "gitlab.com", true
468		default:
469			return "", false
470		}
471	}
472	
473	// RedactURL removes credentials and query parameters from a URL for safe logging.
474	func RedactURL(rawURL string) string {
475		return gitremote.RedactURL(rawURL)
476	}
477	
478	func logFallback(ctx context.Context, operation, fallbackURL, reason string, err error, attrs ...any) {
479		logAttrs := []any{
480			slog.String("operation", operation),
481			slog.String("fallback_url", RedactURL(fallbackURL)),
482			slog.String("reason", reason),
483			slog.String("error", err.Error()),
484		}
485		logAttrs = append(logAttrs, attrs...)
486		logging.Warn(ctx, "checkpoint remote URL resolution fell back to alternate remote URL", logAttrs...)
487	}
488	
489	func resolvePushFallbackURL(ctx context.Context, pushRemoteName, originURL string) (string, error) {
490		if originURL != "" {
491			if strings.TrimSpace(os.Getenv(CheckpointTokenEnvVar)) != "" {
492				if tokenURL, ok := deriveTokenOriginURL(originURL); ok {
493					return tokenURL, nil
494				}
495			}
496			return originURL, nil
497		}
498		if pushRemoteName == "" {
499			return "", fmt.Errorf("no push remote specified and remote %q not found", originRemote)
500		}
501		if pushRemoteName == originRemote {
502			return "", fmt.Errorf("remote %q not found", originRemote)
503		}
504		pushURL, err := GetRemoteURL(ctx, pushRemoteName)
505		if err != nil {
506			return "", err
507		}
508		if strings.TrimSpace(os.Getenv(CheckpointTokenEnvVar)) != "" {
509			if tokenURL, ok := deriveTokenOriginURL(pushURL); ok {
510				return tokenURL, nil
511			}
512		}
513		return pushURL, nil
514	}
