57	// resolve the name to a URL (to avoid persisting promisor settings) should call
58	// ResolveFetchTarget first and pass the resolved target as opts.Remote.
59	func Fetch(ctx context.Context, opts FetchOptions) ([]byte, error) {
60		args := []string{"fetch", "--no-auto-gc"}
61		if opts.NoTags {
62			args = append(args, "--no-tags")
63		}
64		args = append(args, opts.ExtraArgs...)
65		switch {
66		case opts.Shallow:
67			args = append(args, "--depth=1")
68		case opts.Unshallow && isShallowRepository(ctx, opts.Dir):
