131	// CatFiles reads specs through git cat-file --batch.
132	func CatFiles(ctx context.Context, opts CatFilesOptions) map[string]CatFileResult {
133		specs := uniqueStrings(opts.Specs)
134		results := make(map[string]CatFileResult, len(specs))
135		if len(specs) == 0 {
136			return results
137		}
138	
139		args := []string{"cat-file"}
140		args = append(args, opts.ExtraArgs...)
141		args = append(args, "--batch")
142		cmd := newCommand(ctx, args...)
143		if opts.Dir != "" {
144			cmd.Dir = opts.Dir
145		}
146		cmd.Stdin = strings.NewReader(strings.Join(specs, "\n") + "\n")
147		disableTerminalPrompt(cmd)
148		var stderr bytes.Buffer
149		cmd.Stderr = &stderr
150	
151		output, err := cmd.Output()
152		if err != nil {
153			wrapped := catFilesError(err, stderr.String())
154			for _, spec := range specs {
155				results[spec] = CatFileResult{Err: wrapped}
156			}
157			return results
158		}
159	
160		reader := bufio.NewReader(bytes.NewReader(output))
161		for i, spec := range specs {
162			result, parseErr := parseBlobBatchEntry(reader)
163			if parseErr != nil {
164				for _, s := range specs[i:] {
165					results[s] = CatFileResult{Err: parseErr}
166				}
167				break
168			}
169			results[spec] = result
170		}
171		return results
172	}
