174	func parseBlobBatchEntry(reader *bufio.Reader) (CatFileResult, error) {
175		header, err := reader.ReadString('\n')
176		if err != nil {
177			return CatFileResult{}, fmt.Errorf("parse git cat-file batch: %w", err)
178		}
179		header = strings.TrimSuffix(header, "\n")
180	
181		fields := strings.Fields(header)
182		if len(fields) == 2 && fields[1] == "missing" {
183			return CatFileResult{Missing: true}, nil
184		}
185		if len(fields) != 3 {
186			return CatFileResult{}, fmt.Errorf("parse git cat-file batch: unexpected header %q", header)
187		}
188	
189		size, err := strconv.ParseInt(fields[2], 10, 64)
190		if err != nil {
191			return CatFileResult{}, fmt.Errorf("parse git cat-file batch: invalid size %q: %w", fields[2], err)
192		}
193		content := make([]byte, size)
194		if _, err := io.ReadFull(reader, content); err != nil {
195			return CatFileResult{}, fmt.Errorf("parse git cat-file batch: %w", err)
196		}
197		separator, err := reader.ReadByte()
198		if err != nil {
199			return CatFileResult{}, fmt.Errorf("parse git cat-file batch: %w", err)
200		}
201		if separator != '\n' {
202			return CatFileResult{}, fmt.Errorf("parse git cat-file batch: unexpected separator %q", separator)
203		}
204	
205		if fields[1] != "blob" {
206			return CatFileResult{Err: fmt.Errorf("object %s is %s, want blob", fields[0], fields[1])}, nil
207		}
208		return CatFileResult{Content: content}, nil
209	}
