219	func uniqueStrings(values []string) []string {
220		seen := make(map[string]struct{}, len(values))
221		unique := make([]string, 0, len(values))
222		for _, value := range values {
223			if value == "" {
224				continue
225			}
226			if _, ok := seen[value]; ok {
227				continue
228			}
229			seen[value] = struct{}{}
230			unique = append(unique, value)
231		}
232		return unique
233	}
234	
235	// PushResult holds raw porcelain output from git push.
236	type PushResult struct {
237		Output string
238	}
239	
240	// PushOptions configures a git push operation.
241	type PushOptions struct {
242		Remote    string
243		RefSpecs  []string
244		ExtraArgs []string // additional flags before remote
245		Dir       string
246	}
247	
248	// Push runs git push --no-verify --porcelain with token injection.
249	// GIT_TERMINAL_PROMPT=0 is always set.
250	func Push(ctx context.Context, remote, refSpec string) (PushResult, error) {
251		return PushWithOptions(ctx, PushOptions{
252			Remote:   remote,
253			RefSpecs: []string{refSpec},
254		})
255	}
256	
257	// PushWithOptions runs git push --no-verify --porcelain with token injection.
258	// GIT_TERMINAL_PROMPT=0 is always set.
259	func PushWithOptions(ctx context.Context, opts PushOptions) (PushResult, error) {
260		pushTarget, err := resolvePushCommandTarget(ctx, opts.Remote)
261		if err != nil {
262			return PushResult{}, fmt.Errorf("resolve push target: %w", err)
263		}
264	
265		args := []string{"push", "--no-verify", "--porcelain"}
266		args = append(args, opts.ExtraArgs...)
267		args = append(args, pushTarget)
268		args = append(args, opts.RefSpecs...)
269	
270		cmd := newCommand(ctx, args...)
271		if opts.Dir != "" {
272			cmd.Dir = opts.Dir
273		}
274		disableTerminalPrompt(cmd)
275		output, err := cmd.CombinedOutput()
276		if err != nil {
277			return PushResult{Output: string(output)}, fmt.Errorf("git push: %w", err)
278		}
279		return PushResult{Output: string(output)}, nil
280	}
281	
282	// LsRemote runs git ls-remote with token injection.
283	// GIT_TERMINAL_PROMPT=0 is always set. Returns stdout only.
284	func LsRemote(ctx context.Context, remote string, patterns ...string) ([]byte, error) {
285		return lsRemote(ctx, "", remote, patterns...)
286	}
287	
288	// LsRemoteInDir is like LsRemote but runs in a specific directory.
289	func LsRemoteInDir(ctx context.Context, dir, remote string, patterns ...string) ([]byte, error) {
290		return lsRemote(ctx, dir, remote, patterns...)
291	}
292	
293	func lsRemote(ctx context.Context, dir, remote string, patterns ...string) ([]byte, error) {
294		args := append([]string{"ls-remote", remote}, patterns...)
295		cmd := newCommand(ctx, args...)
296		if dir != "" {
297			cmd.Dir = dir
298		}
299		disableTerminalPrompt(cmd)
300		out, err := cmd.Output()
301		if err != nil {
302			return out, fmt.Errorf("git ls-remote: %w", err)
303		}
304		return out, nil
305	}
306	
307	// IsURL returns true if the target looks like a URL rather than a git remote name.
308	func IsURL(target string) bool {
309		return strings.Contains(target, "://") || strings.Contains(target, "@")
310	}
311	
312	// ResolveFetchTarget returns the git fetch target to use. When filtered
313	// fetches are enabled, configured remotes are resolved to their URL so git does
314	// not persist promisor settings onto the remote name.
315	func ResolveFetchTarget(ctx context.Context, target string) (string, error) {
316		if IsURL(target) || isLocalPath(target) || !settings.IsFilteredFetchesEnabled(ctx) {
317			return target, nil
318		}
319		url, err := GetRemoteURL(ctx, target)
320		if err != nil {
321			return "", fmt.Errorf("get remote URL: %w", err)
322		}
323		return url, nil
324	}
325	
326	// isShallowRepository returns true when the git repository at dir is shallow.
327	// An empty dir inherits the parent process's working directory, matching the
328	// semantics callers use when invoking Fetch with empty FetchOptions.Dir.
329	func isShallowRepository(ctx context.Context, dir string) bool {
330		cmd := exec.CommandContext(ctx, "git", "rev-parse", "--is-shallow-repository")
331		cmd.Dir = dir
332		disableTerminalPrompt(cmd)
333		out, err := cmd.Output()
334		if err != nil {
335			return false
336		}
337		return strings.TrimSpace(string(out)) == "true"
338	}
339	
340	// newCommand creates an exec.Cmd for a git operation that may need
341	// checkpoint token authentication. If ENTIRE_CHECKPOINT_TOKEN is set:
342	//   - if the target in args is (or resolves to) an SSH remote, the target is
343	//     rewritten in the args to the equivalent HTTPS URL so git uses HTTP
344	//     transport and our injected Authorization header applies;
345	//   - a Basic auth token is then injected via GIT_CONFIG_COUNT/GIT_CONFIG_KEY_*/
346	//     GIT_CONFIG_VALUE_* environment variables.
347	//
348	// If rewriting fails (unparseable URL, missing owner/repo) the command runs
349	// unmodified and a one-shot warning is printed.
350	// For empty/unset tokens, the command is returned unmodified.
351	//
352	// The remote is extracted from args by skipping the git subcommand and any flags
353	// (arguments starting with "-"). For example, in
354	// ["push", "--no-verify", "origin", "main"], the remote is "origin".
355	func newCommand(ctx context.Context, args ...string) *exec.Cmd {
356		token := strings.TrimSpace(os.Getenv(CheckpointTokenEnvVar))
357	
358		mkCmd := func(finalArgs []string) *exec.Cmd {
359			c := exec.CommandContext(ctx, "git", finalArgs...)
360			c.Stdin = nil // Disconnect stdin to prevent hanging in hook context
361			// Kill the process group on ctx-cancel and force pipes closed after
362			// WaitDelay, so a stuck transport helper can't outlive the caller's
363			// timeout (see terminateOnCancel).
364			terminateOnCancel(c)
365			return c
366		}
367	
368		if token == "" {
369			return mkCmd(args)
370		}
371	
372		if !isValidToken(token) {
373			fmt.Fprintf(os.Stderr, "[entire] Warning: %s contains invalid characters (CR, LF, or other control chars) — token ignored\n", CheckpointTokenEnvVar)
374			return mkCmd(args)
375		}
376	
377		target := extractRemoteFromArgs(args)
378		if target == "" {
379			return mkCmd(args)
380		}
381	
382		newTarget, protocol := resolveTargetForTokenAuth(ctx, target)
383		if newTarget != target {
384			args = replaceFirstPositional(args, newTarget)
385		}
386	
387		cmd := mkCmd(args)
388	
389		switch protocol {
390		case ProtocolSSH:
391			sshTokenWarningOnce.Do(func() {
392				fmt.Fprintf(os.Stderr, "[entire] Warning: %s is set but remote uses SSH — token ignored for SSH remotes\n", CheckpointTokenEnvVar)
393			})
394			return cmd
395		case ProtocolHTTPS:
396			cmd.Env = appendCheckpointTokenEnv(os.Environ(), token)
397			return cmd
398		default:
399			// Unknown protocol (e.g., local path, or resolution failed) — don't inject
400			return cmd
401		}
402	}
403	
404	// resolveTargetForTokenAuth resolves a git target (remote name or URL) to its
405	// effective protocol, rewriting SSH targets to the equivalent HTTPS URL so
406	// token-based auth can be applied. Returns the (possibly rewritten) target and
407	// its final protocol. Protocol is "" when resolution fails (local path,
408	// nonexistent remote, unparseable URL).
409	//
410	// This is only meaningful when ENTIRE_CHECKPOINT_TOKEN is set; callers gate on
411	// that themselves.
412	func resolveTargetForTokenAuth(ctx context.Context, target string) (string, string) {
413		if target == "" || isLocalPath(target) {
414			return target, ""
415		}
416	
417		rawURL := target
418		if !IsURL(target) {
419			var err error
420			rawURL, err = GetRemoteURL(ctx, target)
421			if err != nil {
422				return target, ""
423			}
424		}
425	
426		info, err := ParseURL(rawURL)
427		if err != nil {
428			return target, ""
429		}
430	
431		if info.Protocol == ProtocolSSH {
432			if httpsURL, ok := deriveTokenOriginURL(rawURL); ok {
433				return httpsURL, ProtocolHTTPS
434			}
435			return target, ProtocolSSH
436		}
437	
438		return target, info.Protocol
439	}
440	
441	// replaceFirstPositional returns a copy of args with the first non-flag
442	// argument after args[0] (the git subcommand) replaced by newTarget. Callers
443	// use this to rewrite a remote name/URL after resolution without mutating the
444	// original slice.
445	func replaceFirstPositional(args []string, newTarget string) []string {
446		out := make([]string, len(args))
447		copy(out, args)
448		for i := 1; i < len(out); i++ {
449			if !strings.HasPrefix(out[i], "-") {
450				out[i] = newTarget
451				return out
452			}
453		}
454		return out
455	}
456	
457	// extractRemoteFromArgs finds the remote URL or name from git command args.
458	// It skips the subcommand (first arg) and any flags (args starting with "-"),
459	// returning the first positional argument, which is the remote for push/fetch/ls-remote.
460	func extractRemoteFromArgs(args []string) string {
461		if len(args) < 2 {
462			return ""
463		}
464		// Skip subcommand (e.g., "push", "fetch", "ls-remote").
465		for _, arg := range args[1:] {
466			if !strings.HasPrefix(arg, "-") {
467				return arg
468			}
469		}
470		return ""
471	}
472	
473	// appendCheckpointTokenEnv appends GIT_CONFIG_COUNT-based env vars to inject
474	// an Authorization header into git HTTP requests. The token is sent as a Basic
475	// credential with the format "x-access-token:<token>" (base64-encoded), which
476	// is compatible with GitHub's token authentication.
477	//
478	// Existing GIT_CONFIG_KEY_*/GIT_CONFIG_VALUE_* entries are preserved; the new
479	// http.extraHeader entry is appended at the next free index and
480	// GIT_CONFIG_COUNT is updated accordingly. This keeps caller-injected git
481	// config (e.g., safe.directory, custom CA settings) intact.
482	func appendCheckpointTokenEnv(baseEnv []string, token string) []string {
483		existingCount := 0
484		for _, e := range baseEnv {
485			rest, ok := strings.CutPrefix(e, "GIT_CONFIG_COUNT=")
486			if !ok {
487				continue
488			}
489			if n, err := strconv.Atoi(rest); err == nil && n > 0 {
490				existingCount = n
491			}
492		}
493	
494		// Strip the old GIT_CONFIG_COUNT entry (we'll emit a new one) but keep
495		// GIT_CONFIG_KEY_*/GIT_CONFIG_VALUE_* entries in place.
496		filtered := make([]string, 0, len(baseEnv)+3)
497		for _, e := range baseEnv {
498			if strings.HasPrefix(e, "GIT_CONFIG_COUNT=") {
499				continue
500			}
501			filtered = append(filtered, e)
502		}
503	
504		idx := existingCount
505		encoded := base64.StdEncoding.EncodeToString([]byte("x-access-token:" + token))
506		return append(filtered,
507			fmt.Sprintf("GIT_CONFIG_COUNT=%d", existingCount+1),
508			fmt.Sprintf("GIT_CONFIG_KEY_%d=http.extraHeader", idx),
509			fmt.Sprintf("GIT_CONFIG_VALUE_%d=Authorization: Basic %s", idx, encoded),
510		)
511	}
512	
513	// isValidToken returns false if the token contains control characters (bytes < 0x20
514	// or 0x7F). This prevents HTTP header injection via CR/LF or other control chars
515	// embedded in the token value.
516	func isValidToken(token string) bool {
517		for _, b := range []byte(token) {
518			if b < 0x20 || b == 0x7F {
519				return false
520			}
521		}
522		return true
523	}
524	
525	// resolvePushCommandTarget returns the target to pass to git push. When a
526	// dedicated checkpoint_remote is configured, the checkpoint URL is returned so
527	// the push is routed to the separate checkpoint repo. Otherwise the remote
528	// name is returned unchanged so git uses its own config, updates the
529	// refs/remotes/<name>/<branch> tracking ref, and subsequent calls can use that
530	// tracking ref to skip redundant pushes.
531	//
532	// SSH→HTTPS coercion for token auth is handled by newCommand, which rewrites
533	// the command args or injects per-host config, rather than being baked into
534	// the target here.
535	func resolvePushCommandTarget(ctx context.Context, target string) (string, error) {
536		if target == "" || IsURL(target) || isLocalPath(target) {
537			return target, nil
538		}
539	
540		pushTarget, enabled, err := PushURL(ctx, target)
541		if err != nil {
542			return "", err
543		}
544		if !enabled || pushTarget == "" {
545			return target, nil
546		}
547		return pushTarget, nil
548	}
549	
550	func isLocalPath(target string) bool {
551		return filepath.IsAbs(target) || strings.HasPrefix(target, "./") || strings.HasPrefix(target, "../")
552	}
553	
554	// disableTerminalPrompt sets GIT_TERMINAL_PROMPT=0 on the command,
555	// initializing cmd.Env from os.Environ() if nil.
556	func disableTerminalPrompt(cmd *exec.Cmd) {
557		if cmd.Env == nil {
558			cmd.Env = os.Environ()
559		}
560		cmd.Env = append(cmd.Env, "GIT_TERMINAL_PROMPT=0")
561	}
