//go:build unix

package strategy

import (
	"context"
	"os"
	"path/filepath"
	"testing"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/paths"

	"github.com/stretchr/testify/require"
)

// TestDoPushBranch_SharedBudget_BoundsTotalWallClock proves the checkpoint push is
// bounded by a single shared deadline rather than a fresh per-attempt timeout.
//
// Regression for the ~4-minute pre-push hang: against a stuck transport the initial
// push burned its full per-attempt timeout, then the fetch+rebase recovery and the
// retry each minted their own fresh timeout, so `git push` blocked for ~2x the
// intended bound. With a shared budget, the first push consumes the budget and the
// recovery + retry fail fast (context already expired), so the whole operation
// returns at ~budget.
//
// Mechanism: a hanging GIT_SSH_COMMAND (a script that ignores its args and just
// sleeps) makes `git push` to an ssh:// URL block in the transport until the
// budget's deadline SIGKILLs the process group. The script sleeps well past the
// asserted upper bound, so a regression (per-attempt timeouts) would blow past it;
// it self-exits as a backstop if the kill path ever regresses.
//
// Not parallel: uses t.Setenv and overrides the package-level checkpointPushBudget.
func TestDoPushBranch_SharedBudget_BoundsTotalWallClock(t *testing.T) {
	// Shrink the production 60s budget so the test runs in seconds.
	const budget = 2 * time.Second
	restoreBudget := checkpointPushBudget
	checkpointPushBudget = budget
	t.Cleanup(func() { checkpointPushBudget = restoreBudget })

	// A transport that hangs well past the upper bound asserted below. git exec's
	// it for the ssh:// URL via GIT_SSH_COMMAND; it ignores its args and just sleeps.
	hangScript := filepath.Join(t.TempDir(), "hang.sh")
	require.NoError(t, os.WriteFile(hangScript, []byte("#!/bin/sh\nexec sleep 8\n"), 0o755)) //nolint:gosec // test helper script must be executable
	t.Setenv("GIT_SSH_COMMAND", hangScript)
	// Keep token auth out of the path: with a token set, newCommand would rewrite
	// the ssh:// URL to https:// and our GIT_SSH_COMMAND hang would never run.
	t.Setenv("ENTIRE_CHECKPOINT_TOKEN", "")

	tmpDir := setupRepoWithCheckpointBranch(t)
	t.Chdir(tmpDir)

	// Suppress the progress dots / warnings doPushBranch writes to os.Stderr.
	restoreStderr := captureStderr(t)
	defer restoreStderr()

	// ssh:// URL so git invokes GIT_SSH_COMMAND (our hang) for the transport.
	const target = "ssh://git@localhost/checkpoints.git"

	start := time.Now()
	err := doPushBranch(context.Background(), target, paths.MetadataBranchName)
	elapsed := time.Since(start)

	require.NoError(t, err, "doPushBranch degrades gracefully on a stuck transport")

	// Upper bound: the whole operation shares one budget. A per-attempt regression
	// (push + recovery + retry each minting a fresh timeout) would land at or above
	// 2x the budget; the hang script outlives this bound, so any failure to enforce
	// the shared budget pushes elapsed past it.
	require.Less(t, elapsed, 5*time.Second,
		"doPushBranch should return at ~budget, not stack multiple full timeouts; took %s", elapsed)
	// Lower bound: confirm the push actually engaged the transport and was cut off
	// by the budget, rather than failing instantly for an unrelated reason (which
	// would make the upper-bound assertion meaningless).
	require.GreaterOrEqual(t, elapsed, budget/2,
		"push should have run until the budget deadline; took %s", elapsed)
}

